    CONSTRAINT "line_activity_log_event_type_check" CHECK (("event_type" = ANY (ARRAY['topup_requested'::"text", 'topup_success'::"text", 'topup_failed'::"text", 'topup_refunded'::"text", 'topup_cancelled'::"text", 'topup_retry_queued'::"text", 'reminder_sent'::"text", 'status_change'::"text", 'health_update'::"text", 'tier_change'::"text", 'paused'::"text", 'resumed'::"text", 'created'::"text", 'grace_period_entered'::"text", 'rescue_topup_triggered'::"text", 'validity_extended'::"text"])))
);

