CREATE OR REPLACE FUNCTION "public"."emit_upcoming_refill_low_balance_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r RECORD;
  v_count INTEGER := 0;
  v_available NUMERIC;
  v_phone TEXT;
BEGIN
  FOR r IN
    SELECT te.id AS execution_id,
           te.sim_line_id,
           te.user_id,
           te.amount,
           te.execution_time,
           te.execution_type,
           sl.phone_number,
           sl.nickname
    FROM public.topup_executions te
    JOIN public.sim_lines sl ON sl.id = te.sim_line_id
    WHERE te.status = 'pending'
      AND te.execution_type IN ('refill_mini', 'refill_custom')
      AND te.execution_time > now()
      AND te.execution_time <= now() + INTERVAL '7 days'
      AND sl.status = 'active'
      AND COALESCE(sl.protection_paused, false) = false
  LOOP
    -- Calculate user's available wallet balance
    SELECT (w.balance - COALESCE(
      (SELECT SUM(h.amount) FROM public.wallet_holds h WHERE h.user_id = r.user_id AND h.status = 'active'),
      0.00
    )) INTO v_available
    FROM public.wallets w
    WHERE w.user_id = r.user_id;

    IF v_available IS NOT NULL AND v_available < r.amount THEN
      -- Deduplication: Ensure we don't spam. Only 1 notification per SIM line per 24 hours.
      IF NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = r.user_id
          AND n.sim_line_id = r.sim_line_id
          AND n.category = 'wallet'
          AND n.created_at >= now() - INTERVAL '24 hours'
          AND n.title = 'Low Wallet Balance for Upcoming Auto-Refill'
      ) THEN
        v_phone := COALESCE(NULLIF(r.nickname, ''), r.phone_number, 'Your SIM line');

        INSERT INTO public.notifications (
          user_id, category, title, body, action_url, sim_line_id, delivered_via, is_read, created_at
        ) VALUES (
          r.user_id,
          'wallet',
          'Low Wallet Balance for Upcoming Auto-Refill',
          'Your scheduled recharge of $' || to_char(r.amount, 'FM999990.00') || ' for ' || v_phone || ' is due on ' || to_char(r.execution_time, 'Mon DD') || '. Your available wallet balance ($' || to_char(GREATEST(v_available, 0.00), 'FM999990.00') || ') is low. Please top up your wallet to ensure continuous protection.',
          '/wallet',
          r.sim_line_id,
          ARRAY['push'::text],
          false,
          now()
        );

        INSERT INTO public.line_activity_log (
          sim_line_id, user_id, event_type, description, metadata, created_at
        ) VALUES (
          r.sim_line_id,
          r.user_id,
          'reminder_sent',
          'Low wallet balance reminder sent for upcoming auto-refill',
          jsonb_build_object(
            'execution_id', r.execution_id,
            'execution_time', r.execution_time,
            'refill_amount', r.amount,
            'available_balance', v_available
          ),
          clock_timestamp()
        );

        v_count := v_count + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$_$;

REVOKE ALL ON FUNCTION public."emit_upcoming_refill_low_balance_reminders"() FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."emit_upcoming_refill_low_balance_reminders"() TO service_role;

CREATE OR REPLACE FUNCTION "public"."process_due_notifications"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE r record; v_period interval; v_next timestamptz; v_key text;
BEGIN
  FOR r IN SELECT s.*,l.phone_number FROM public.scheduled_topups s
    JOIN public.sim_lines l ON l.id=s.sim_line_id AND l.user_id=s.user_id
    WHERE s.is_active AND s.status='active' AND s.schedule_type='notify' AND s.next_execution_at<=now()
    ORDER BY s.next_execution_at LIMIT 1000 FOR UPDATE OF s SKIP LOCKED
  LOOP
    v_key:='notify_due:'||r.id||':'||r.next_execution_at;
    v_period:=CASE WHEN coalesce(r.frequency_days,0)<=0 THEN interval '1 hour' ELSE r.frequency_days*interval '1 day' END;
    -- One catch-up event, then advance from the intended due time, not now().
    v_next:=r.next_execution_at+v_period*(floor(extract(epoch FROM (now()-r.next_execution_at))/extract(epoch FROM v_period))+1);
    INSERT INTO public.notifications(user_id,sim_line_id,category,title,body,event_type,schema_version,source_event_key,
      action_url,occurred_at,expires_at,template_data)
    VALUES(r.user_id,r.sim_line_id,'line_critical','Recharge reminder',
      'SIM line ending '||right(regexp_replace(r.phone_number,'[^0-9]','','g'),4)||' is due for recharge. Open KeepSIMs to review your line.',
      'recharge_due_today',2,v_key,'/sim-lines/detail/'||r.sim_line_id,r.next_execution_at,now()+interval '24 hours',
      jsonb_build_object('scheduled_topup_id',r.id,'amount',r.amount,'currency',r.currency)) ON CONFLICT DO NOTHING;
    INSERT INTO public.line_activity_log(sim_line_id,user_id,event_type,metadata)
      VALUES(r.sim_line_id,r.user_id,'reminder_sent',jsonb_build_object('source_event_key',v_key,'schedule_type','notify'));
    UPDATE public.scheduled_topups SET last_execution_at=now(),next_execution_at=v_next,retry_count=0,
      whatsapp_sent_this_cycle=false,updated_at=now() WHERE id=r.id;
  END LOOP;
  PERFORM public.emit_upcoming_refill_low_balance_reminders();
  PERFORM public.emit_missing_recharge_date_reminders();
  PERFORM public.emit_urgent_deactivation_alerts(false);
END;
$$;

REVOKE ALL ON FUNCTION public."process_due_notifications"() FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."process_due_notifications"() TO service_role;

CREATE OR REPLACE FUNCTION "public"."emit_missing_recharge_date_reminders"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_count integer;
BEGIN
  -- A manual sweep and the hourly sweep share one transaction lock.
  PERFORM pg_advisory_xact_lock(hashtextextended('keepsims:missing-recharge-emitter',0));
  WITH candidates AS (
    SELECT l.id,l.user_id,l.phone_number,l.created_at,
      CASE WHEN public.notification_channel_eligible(l.user_id,l.id,'email',NULL) THEN 1 ELSE 7 END days,
      coalesce(up.language,'en') language
    FROM public.sim_lines l LEFT JOIN public.user_preferences up ON up.user_id=l.user_id
    WHERE l.status='active' AND l.last_topup_at IS NULL AND NOT l.protection_paused
  ), inserted AS (
    INSERT INTO public.notifications(user_id,sim_line_id,category,title,body,event_type,schema_version,
      source_event_key,action_url,occurred_at,created_at,expires_at,template_data)
    SELECT user_id,id,'system',CASE WHEN language LIKE 'ar%' THEN 'أضف تاريخ آخر شحن' ELSE 'Add your last recharge date' END,
      CASE WHEN language LIKE 'ar%' THEN 'أضف تاريخ آخر شحن للخط المنتهي بـ ' ELSE 'Add the last recharge date for SIM line ending ' END
        ||right(regexp_replace(phone_number,'[^0-9]','','g'),4),
      'recharge_date_missing',2,'missing-recharge:'||id||':'||floor(extract(epoch FROM p_now)/(days*86400)),
      '/sim-lines/detail/'||id,p_now,p_now,p_now+interval '24 hours',jsonb_build_object('cadence_days',days)
    FROM candidates c WHERE created_at<=p_now-make_interval(days=>c.days)
      AND NOT EXISTS(SELECT 1 FROM public.notifications n WHERE n.sim_line_id=c.id AND n.event_type='recharge_date_missing'
        AND n.created_at>p_now-make_interval(days=>c.days))
    ON CONFLICT DO NOTHING RETURNING id
  ) SELECT count(*) INTO v_count FROM inserted;
  RETURN v_count;
END;
$$;

REVOKE ALL ON FUNCTION public."emit_missing_recharge_date_reminders"(timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."emit_missing_recharge_date_reminders"(timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION "public"."emit_urgent_deactivation_alerts"("p_dry_run" boolean DEFAULT false, "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_enabled BOOLEAN := false;
  v_candidate RECORD;
  v_emitted_count INT := 0;
  v_candidates_list jsonb := '[]'::jsonb;
  v_event_key TEXT;
  v_line_label TEXT;
  v_user_lang TEXT;
  v_title TEXT;
  v_body TEXT;
  v_inserted_id uuid;
BEGIN
  -- 1. Check global feature switch
  SELECT (config_value = 'true') INTO v_is_enabled
  FROM public.system_configs
  WHERE config_key = 'ALERT_CLOCK_SCHEDULER_ENABLED';

  IF NOT COALESCE(v_is_enabled, false) AND NOT p_dry_run THEN
    RETURN jsonb_build_object(
      'success', true,
      'scheduler_enabled', false,
      'emitted_count', 0,
      'message', 'ALERT_CLOCK_SCHEDULER_ENABLED is false; emission withheld'
    );
  END IF;

  -- 2. First refresh all active line clock states to ensure real-time evaluation
  PERFORM public.sync_all_sim_line_alert_clocks(p_now);

  -- 3. Loop over candidates currently in 48-hour window
  FOR v_candidate IN
    SELECT 
      cs.*,
      sl.phone_number,
      sl.nickname,
      up.language AS user_language
    FROM public.sim_line_alert_clock_states cs
    JOIN public.sim_lines sl ON sl.id = cs.sim_line_id
    LEFT JOIN public.user_preferences up ON up.user_id = cs.user_id
    WHERE cs.state = 'eligible'
      AND cs.is_within_48h = true
      AND cs.alert_cycle_token IS NOT NULL
      AND cs.alert_emitted_at IS NULL
      AND sl.status = 'active'
      AND COALESCE(sl.protection_paused, false) = false
  LOOP
    v_event_key := 'deactivation_48h:' || v_candidate.sim_line_id || ':' || v_candidate.alert_cycle_token;

    -- Idempotency check: has this specific event key already been inserted into notifications?
    IF NOT EXISTS (
      SELECT 1 FROM public.notifications 
      WHERE source_event_key = v_event_key
    ) THEN
      -- Prepare label & language
      v_user_lang := COALESCE(v_candidate.user_language, 'en');
      v_line_label := CASE 
        WHEN NULLIF(btrim(COALESCE(v_candidate.nickname, '')), '') IS NOT NULL 
          THEN btrim(v_candidate.nickname) || ' · ' || right(regexp_replace(v_candidate.phone_number, '\D', '', 'g'), 4)
        ELSE 'Line ending ' || right(regexp_replace(v_candidate.phone_number, '\D', '', 'g'), 4)
      END;

      IF v_user_lang LIKE 'ar%' THEN
        v_title := '⚠️ تحذير: الخط معرض للإلغاء خلال 48 ساعة';
        v_body := 'الرقم ' || v_line_label || ' قارب على مهلة الإلغاء المقدرة بحوالي يومين (' || 
                  to_char(v_candidate.deactivation_cutoff_at, 'YYYY-MM-DD') || 
                  '). يرجى اتخاذ الإجراء اللازم فوراً للحفاظ على صلاحية الرقم.';
      ELSE
        v_title := '⚠️ Deactivation Imminent: About 48h Remaining';
        v_body := v_line_label || ' is within approximately 2 days of carrier deactivation cutoff (' || 
                  to_char(v_candidate.deactivation_cutoff_at, 'YYYY-MM-DD') || 
                  '). Take action now to keep your line active.';
      END IF;

      v_candidates_list := v_candidates_list || jsonb_build_object(
        'sim_line_id', v_candidate.sim_line_id,
        'phone_number', v_candidate.phone_number,
        'carrier_name', v_candidate.carrier_name,
        'hours_remaining', v_candidate.hours_remaining,
        'deactivation_cutoff_at', v_candidate.deactivation_cutoff_at,
        'event_key', v_event_key
      );

      IF NOT p_dry_run THEN
        -- Insert logical alert event
        INSERT INTO public.notifications (
          user_id,
          category,
          title,
          body,
          action_url,
          sim_line_id,
          delivered_via,
          is_read,
          schema_version,
          event_type,
          source_event_key,
          occurred_at,
          template_version,
          template_data,
          target,
          created_at
        ) VALUES (
          v_candidate.user_id,
          'line_critical',
          v_title,
          v_body,
          '/sim-lines/detail/' || v_candidate.sim_line_id,
          v_candidate.sim_line_id,
          ARRAY[]::text[], -- Will be populated truthfully by dispatcher upon attempt outcomes!
          false,
          2,
          'line_deactivation_imminent',
          v_event_key,
          p_now,
          1,
          jsonb_build_object(
            'line', v_line_label,
            'carrier_name', v_candidate.carrier_name,
            'hours_remaining', v_candidate.hours_remaining,
            'cutoff_at', v_candidate.deactivation_cutoff_at,
            'activity_requirement', v_candidate.activity_requirement
          ),
          jsonb_build_object('route', '/sim-lines/detail/:id', 'id', v_candidate.sim_line_id),
          p_now
        )
        ON CONFLICT DO NOTHING
        RETURNING id INTO v_inserted_id;

        IF v_inserted_id IS NULL THEN
          -- Another scheduler run already inserted this logical event.
          UPDATE public.sim_line_alert_clock_states
          SET alert_emitted_at = p_now, updated_at = now()
          WHERE sim_line_id = v_candidate.sim_line_id;
          CONTINUE;
        END IF;

        -- Mark alert emitted for this cycle token on state table
        UPDATE public.sim_line_alert_clock_states
        SET alert_emitted_at = p_now,
            updated_at = now()
        WHERE sim_line_id = v_candidate.sim_line_id;

        v_emitted_count := v_emitted_count + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'dry_run', p_dry_run,
    'candidates_count', jsonb_array_length(v_candidates_list),
    'emitted_count', v_emitted_count,
    'candidates', v_candidates_list,
    'evaluated_at', p_now
  );
END;
$$;

REVOKE ALL ON FUNCTION public."emit_urgent_deactivation_alerts"(boolean, timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."emit_urgent_deactivation_alerts"(boolean, timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION "public"."notification_channel_eligible"("p_user_id" "uuid", "p_sim_line_id" "uuid", "p_channel" "text", "p_event_type" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.notification_channel_catalog c
    WHERE c.channel_key=p_channel AND c.is_globally_enabled
      AND CASE WHEN p_channel IN ('push','telegram') THEN true
      WHEN p_sim_line_id IS NULL THEN p_event_type='weekly_digest' AND p_channel='email' AND EXISTS (
        SELECT 1 FROM public.sim_lines l WHERE l.user_id=p_user_id
          AND l.notification_entitlement_verified
          AND l.status NOT IN ('deleted','canceled','archived')
          AND lower(coalesce(nullif(l.plan_type,''),nullif(l.protection_tier,''),'basic')) IN ('standard','premium')
          AND (l.plan_expires_at IS NULL OR l.plan_expires_at>now())
          AND (c.min_tier<>'premium' OR lower(coalesce(nullif(l.plan_type,''),l.protection_tier))='premium')
      ) ELSE EXISTS (
        SELECT 1 FROM public.sim_lines l WHERE l.id=p_sim_line_id AND l.user_id=p_user_id
          AND l.notification_entitlement_verified
          AND l.status NOT IN ('deleted','canceled','archived')
          AND lower(coalesce(nullif(l.plan_type,''),nullif(l.protection_tier,''),'basic')) IN ('standard','premium')
          AND (l.plan_expires_at IS NULL OR l.plan_expires_at>now())
          AND (c.min_tier<>'premium' OR lower(coalesce(nullif(l.plan_type,''),l.protection_tier))='premium')
      ) END
  );
$$;

REVOKE ALL ON FUNCTION public."notification_channel_eligible"(uuid, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."notification_channel_eligible"(uuid, uuid, text, text) TO service_role;

CREATE OR REPLACE FUNCTION "public"."trg_fn_dispatch_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE v_channels text[]; v_enabled boolean; v_category_channels text[]; v_language text;
BEGIN
  SELECT is_enabled,channels INTO v_enabled,v_category_channels FROM public.alert_settings
    WHERE user_id=NEW.user_id AND category=NEW.category;
  IF NOT coalesce(v_enabled,NEW.category<>'promo') THEN RETURN NEW; END IF;
  IF NEW.sim_line_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sim_lines WHERE id=NEW.sim_line_id AND user_id=NEW.user_id) THEN RETURN NEW; END IF;
  SELECT language INTO v_language FROM public.user_preferences WHERE user_id=NEW.user_id;
  SELECT array_agg(c.channel_key ORDER BY c.sort_order) INTO v_channels
  FROM public.notification_channel_catalog c LEFT JOIN public.notification_channels nc
    ON nc.user_id=NEW.user_id AND nc.channel_type=c.channel_key
  WHERE public.notification_channel_eligible(NEW.user_id,NEW.sim_line_id,c.channel_key,NEW.event_type)
    AND coalesce(nc.is_enabled,c.channel_key='push')
    AND (v_category_channels IS NULL OR c.channel_key=ANY(v_category_channels))
    AND (NEW.event_type IS DISTINCT FROM 'weekly_digest' OR c.channel_key<>'email' OR NEW.template_data->>'digest_paid_eligible'='true')
    AND (NEW.event_type<>'notification_test' OR NEW.template_data->>'test_channel' IS NULL OR c.channel_key=NEW.template_data->>'test_channel');
  IF coalesce(cardinality(v_channels),0)=0 THEN RETURN NEW; END IF;
  INSERT INTO public.notification_dispatch_jobs(notification_id,user_id,payload,next_attempt_at)
    VALUES(NEW.id,NEW.user_id,jsonb_build_object('notification_id',NEW.id,'user_id',NEW.user_id,
      'category',NEW.category,'title',NEW.title,'body',NEW.body,'action_url',NEW.action_url,'sim_line_id',NEW.sim_line_id,
      'channels',v_channels,'event_type',NEW.event_type,'source_event_key',NEW.source_event_key,
      'target',NEW.target,'template_data',coalesce(NEW.template_data,'{}'),'language',coalesce(v_language,'en'),
      'schema_version',NEW.schema_version,'occurred_at',NEW.occurred_at,'template_version',NEW.template_version),
      greatest(now(),coalesce(NEW.scheduled_at,now()))) ON CONFLICT(notification_id) DO NOTHING;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public."trg_fn_dispatch_notification"() FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."trg_fn_dispatch_notification"() TO service_role;

CREATE OR REPLACE FUNCTION "public"."trg_fn_notify_system_alert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.notifications
    (user_id, category, title, body, action_url, delivered_via, is_read)
  SELECT p.id, 'system',
         'System alert: ' || NEW.kind,
         NEW.message,
         '/notifications', ARRAY['push']::text[], false
  FROM public.profiles p
  WHERE p.is_power_user = true;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public."trg_fn_notify_system_alert"() FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."trg_fn_notify_system_alert"() TO service_role;

CREATE OR REPLACE FUNCTION "public"."calculate_sim_line_alert_clock"("p_sim_line_id" "uuid", "p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_line RECORD;
  v_carrier RECORD;
  v_rule RECORD;
  v_exec RECORD;
  v_usage RECORD;
  v_stale_limit_days INT := 180;
  
  v_state TEXT;
  v_reason TEXT := NULL;
  v_activity_type TEXT := NULL;
  v_activity_at TIMESTAMPTZ := NULL;
  v_activity_amount NUMERIC := NULL;
  v_cutoff_at TIMESTAMPTZ := NULL;
  v_hours_remaining NUMERIC := NULL;
  v_is_within_48h BOOLEAN := false;
  v_precision TEXT := 'date';
  v_cycle_token TEXT := NULL;
  v_prev_alert_emitted_at TIMESTAMPTZ := NULL;
  v_prev_cycle_token TEXT := NULL;
BEGIN
  -- Read stale limit config
  SELECT COALESCE(NULLIF(config_value, '')::integer, 180) INTO v_stale_limit_days
  FROM public.system_configs WHERE config_key = 'ALERT_CLOCK_STALE_RULE_DAYS';

  -- 1. Fetch SIM Line
  SELECT * INTO v_line FROM public.sim_lines WHERE id = p_sim_line_id;
  IF v_line.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SIM line not found');
  END IF;

  -- Check existing clock state to preserve emission history if in same cycle
  SELECT alert_cycle_token, alert_emitted_at 
  INTO v_prev_cycle_token, v_prev_alert_emitted_at
  FROM public.sim_line_alert_clock_states
  WHERE sim_line_id = p_sim_line_id;

  -- 2. State checks on line status
  IF v_line.status <> 'active' THEN
    v_state := 'inactive_line';
    v_reason := 'SIM line is currently ' || COALESCE(v_line.status, 'inactive');
  ELSIF v_line.carrier_status IN ('deactivated', 'terminated', 'blocked') THEN
    v_state := 'carrier_deactivated';
    v_reason := 'Carrier reported this line as ' || v_line.carrier_status;
  END IF;

  -- 3. Fetch Carrier and Carrier Rule
  SELECT * INTO v_carrier FROM public.carriers WHERE id = v_line.carrier_id;

  SELECT * INTO v_rule 
  FROM public.carrier_rules 
  WHERE id = v_line.carrier_rule_id
     OR (v_line.carrier_rule_id IS NULL AND carrier_id = v_line.carrier_id)
  ORDER BY (id = v_line.carrier_rule_id) DESC NULLS LAST, updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_state IS NULL THEN
    IF v_rule.id IS NULL OR v_rule.inactivity_limit_days IS NULL OR v_rule.inactivity_limit_days <= 0 THEN
      v_state := 'missing_rule';
      v_reason := 'No verified carrier deactivation rule found for this network';
    ELSIF NULLIF(btrim(COALESCE(v_rule.rule_source_url, '')), '') IS NULL OR v_rule.last_verified_at IS NULL OR v_rule.last_verified_at < (p_now - make_interval(days => v_stale_limit_days)) THEN
      v_state := 'stale_rule';
      v_reason := 'Carrier deactivation policy needs a source and recent verification by KeepSIMs operators';
    END IF;
  END IF;

  -- 4. Evaluate Qualifying Activity based on rule semantics
  IF v_state IS NULL THEN
    -- Check for latest confirmed automated topup execution
    SELECT * INTO v_exec
    FROM public.topup_executions
    WHERE sim_line_id = p_sim_line_id
      AND status IN ('success', 'completed')
      AND COALESCE(completed_at, executed_at, created_at) <= p_now
    ORDER BY COALESCE(completed_at, executed_at, created_at) DESC
    LIMIT 1;

    IF v_rule.activity_requirement = 'usage_required' THEN
      -- The current activity log has no carrier-confirmed call/SMS/data events.
      -- A liveness ping proves only that the SIM responds, not qualifying usage.
      v_state := 'needs_qualifying_usage';
      v_reason := 'Carrier requires confirmed outgoing call, SMS, or cellular data activity; no verified usage event is available.';
    ELSIF v_rule.activity_requirement = 'min_denomination' THEN
      -- Must meet threshold
      DECLARE
        v_min_threshold NUMERIC := COALESCE(v_rule.validity_qualifying_topup_amount, v_rule.minimum_topup_amount, 0);
      BEGIN
        SELECT * INTO v_exec
        FROM public.topup_executions
        WHERE sim_line_id = p_sim_line_id
          AND status = 'success'
          AND currency = 'USD'
          AND amount >= v_min_threshold
          AND COALESCE(completed_at, executed_at, created_at) <= p_now
        ORDER BY COALESCE(completed_at, executed_at, created_at) DESC
        LIMIT 1;

        IF v_exec.id IS NOT NULL THEN
          v_activity_type := 'confirmed_topup';
          v_activity_at := COALESCE(v_exec.completed_at, v_exec.executed_at, v_exec.created_at);
          v_activity_amount := v_exec.amount;
          v_precision := 'timestamp';
        ELSIF v_line.last_topup_at IS NOT NULL THEN
          -- Check if manual recharge has logged amount in activity log
          SELECT (metadata->>'amount')::numeric INTO v_activity_amount
          FROM public.line_activity_log
          WHERE sim_line_id = p_sim_line_id
            AND event_type = 'validity_extended'
            AND (metadata->>'recharge_date')::timestamptz = v_line.last_topup_at
          ORDER BY created_at DESC
          LIMIT 1;

          IF v_activity_amount IS NOT NULL AND v_activity_amount >= v_min_threshold THEN
            v_activity_type := 'manual_topup';
            v_activity_at := v_line.last_topup_at;
            v_precision := 'date';
          ELSIF v_activity_amount IS NULL THEN
            v_state := 'needs_amount';
            v_reason := 'Carrier requires top-up of at least $' || v_min_threshold || '. Please confirm the amount of your recharge.';
          ELSE
            v_state := 'needs_amount';
            v_reason := 'Last top-up of $' || v_activity_amount || ' is below the carrier threshold of $' || v_min_threshold || '.';
          END IF;
        ELSE
          v_state := 'needs_activity_date';
          v_reason := 'No qualifying recharge recorded for this line';
        END IF;
      END;

    ELSE
      -- recharge_ok (default)
      IF v_exec.id IS NOT NULL AND (v_line.last_topup_at IS NULL OR COALESCE(v_exec.completed_at, v_exec.executed_at) >= v_line.last_topup_at) THEN
        v_activity_type := 'confirmed_topup';
        v_activity_at := COALESCE(v_exec.completed_at, v_exec.executed_at, v_exec.created_at);
        v_activity_amount := v_exec.amount;
        v_precision := 'timestamp';
      ELSIF v_line.last_topup_at IS NOT NULL THEN
        -- Timestamp sanity check
        IF v_line.last_topup_at > (p_now + interval '1 day') THEN
          v_state := 'needs_activity_date';
          v_reason := 'Recorded recharge date is in the future. Please update to a valid date.';
        ELSIF v_line.last_topup_at < (p_now - interval '730 days') THEN
          v_state := 'needs_activity_date';
          v_reason := 'Recorded recharge date is over 2 years old. Please record your latest recharge.';
        ELSE
          v_activity_type := 'manual_topup';
          v_activity_at := v_line.last_topup_at;
          v_precision := 'date';
        END IF;
      ELSE
        v_state := 'needs_activity_date';
        v_reason := 'No recharge date recorded. Self-report your last recharge date to activate the Alert Clock.';
      END IF;
    END IF;
  END IF;

  -- 5. Final Calculation for Eligible State
  IF v_state IS NULL AND v_activity_at IS NOT NULL THEN
    v_state := 'eligible';
    -- NEVER add grace_period_days to deactivation cutoff!
    IF v_precision = 'date' THEN
      -- Keep a day-resolution UTC comparison instant only for scheduling.
      -- The app must display a date estimate, never this invented hour.
      v_cutoff_at := ((v_activity_at AT TIME ZONE 'UTC')::date
        + v_rule.inactivity_limit_days)::timestamp AT TIME ZONE 'UTC';
    ELSE
      v_cutoff_at := v_activity_at + (v_rule.inactivity_limit_days || ' days')::interval;
    END IF;
    v_hours_remaining := round((extract(epoch from (v_cutoff_at - p_now)) / 3600.0)::numeric, 1);
    
    -- Within 48h boundary
    v_is_within_48h := (v_hours_remaining <= 48.0 AND v_hours_remaining > 0.0);
    
    -- Unique token for this activity cycle
    v_cycle_token := md5(
      p_sim_line_id::text || ':' || 
      v_activity_at::text || ':' || 
      COALESCE(v_rule.id::text, '') || ':' || 
      COALESCE(v_rule.inactivity_limit_days::text, '') || ':' ||
      COALESCE(v_rule.activity_requirement, '') || ':' ||
      COALESCE(v_rule.validity_qualifying_topup_amount::text, '')
    );

    -- If cycle token changed from previous cycle, reset alert emission
    IF v_prev_cycle_token IS DISTINCT FROM v_cycle_token THEN
      v_prev_alert_emitted_at := NULL;
    END IF;
  ELSE
    v_cutoff_at := NULL;
    v_hours_remaining := NULL;
    v_is_within_48h := false;
    v_cycle_token := NULL;
    v_prev_alert_emitted_at := NULL;
  END IF;

  -- 6. Upsert into public.sim_line_alert_clock_states
  INSERT INTO public.sim_line_alert_clock_states (
    sim_line_id,
    user_id,
    carrier_id,
    carrier_rule_id,
    carrier_name,
    activity_requirement,
    inactivity_limit_days,
    qualifying_activity_type,
    qualifying_activity_at,
    qualifying_activity_amount,
    deactivation_cutoff_at,
    precision,
    state,
    ineligibility_reason,
    hours_remaining,
    is_within_48h,
    rule_source_url,
    rule_last_verified_at,
    alert_cycle_token,
    alert_emitted_at,
    evaluated_at,
    updated_at
  ) VALUES (
    v_line.id,
    v_line.user_id,
    v_line.carrier_id,
    v_rule.id,
    v_carrier.name,
    COALESCE(v_rule.activity_requirement, 'recharge_ok'),
    v_rule.inactivity_limit_days,
    v_activity_type,
    v_activity_at,
    v_activity_amount,
    v_cutoff_at,
    v_precision,
    v_state,
    v_reason,
    v_hours_remaining,
    v_is_within_48h,
    v_rule.rule_source_url,
    v_rule.last_verified_at,
    v_cycle_token,
    v_prev_alert_emitted_at,
    p_now,
    now()
  )
  ON CONFLICT (sim_line_id) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    carrier_id = EXCLUDED.carrier_id,
    carrier_rule_id = EXCLUDED.carrier_rule_id,
    carrier_name = EXCLUDED.carrier_name,
    activity_requirement = EXCLUDED.activity_requirement,
    inactivity_limit_days = EXCLUDED.inactivity_limit_days,
    qualifying_activity_type = EXCLUDED.qualifying_activity_type,
    qualifying_activity_at = EXCLUDED.qualifying_activity_at,
    qualifying_activity_amount = EXCLUDED.qualifying_activity_amount,
    deactivation_cutoff_at = EXCLUDED.deactivation_cutoff_at,
    precision = EXCLUDED.precision,
    state = EXCLUDED.state,
    ineligibility_reason = EXCLUDED.ineligibility_reason,
    hours_remaining = EXCLUDED.hours_remaining,
    is_within_48h = EXCLUDED.is_within_48h,
    rule_source_url = EXCLUDED.rule_source_url,
    rule_last_verified_at = EXCLUDED.rule_last_verified_at,
    alert_cycle_token = EXCLUDED.alert_cycle_token,
    alert_emitted_at = EXCLUDED.alert_emitted_at,
    evaluated_at = EXCLUDED.evaluated_at,
    updated_at = now();

  RETURN jsonb_build_object(
    'sim_line_id', v_line.id,
    'carrier_name', v_carrier.name,
    'state', v_state,
    'is_eligible', (v_state = 'eligible'),
    'ineligibility_reason', v_reason,
    'activity_requirement', COALESCE(v_rule.activity_requirement, 'recharge_ok'),
    'inactivity_limit_days', v_rule.inactivity_limit_days,
    'qualifying_activity_type', v_activity_type,
    'qualifying_activity_at', v_activity_at,
    'deactivation_cutoff_at', v_cutoff_at,
    'hours_remaining', v_hours_remaining,
    'is_within_48h', v_is_within_48h,
    'precision', v_precision,
    'rule_source_url', v_rule.rule_source_url,
    'rule_last_verified_at', v_rule.last_verified_at,
    'evaluated_at', p_now
  );
END;
$_$;

REVOKE ALL ON FUNCTION public."calculate_sim_line_alert_clock"(uuid, timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."calculate_sim_line_alert_clock"(uuid, timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION "public"."sync_all_sim_line_alert_clocks"("p_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line RECORD;
  v_total INT := 0;
  v_eligible INT := 0;
  v_within_48h INT := 0;
  v_needs_date INT := 0;
  v_needs_usage INT := 0;
  v_needs_amount INT := 0;
  v_stale_rule INT := 0;
  v_res jsonb;
BEGIN
  FOR v_line IN SELECT id FROM public.sim_lines WHERE status = 'active' LOOP
    v_res := public.calculate_sim_line_alert_clock(v_line.id, p_now);
    v_total := v_total + 1;

    IF (v_res->>'state') = 'eligible' THEN
      v_eligible := v_eligible + 1;
      IF (v_res->>'is_within_48h')::boolean THEN
        v_within_48h := v_within_48h + 1;
      END IF;
    ELSIF (v_res->>'state') = 'needs_activity_date' THEN
      v_needs_date := v_needs_date + 1;
    ELSIF (v_res->>'state') = 'needs_qualifying_usage' THEN
      v_needs_usage := v_needs_usage + 1;
    ELSIF (v_res->>'state') = 'needs_amount' THEN
      v_needs_amount := v_needs_amount + 1;
    ELSIF (v_res->>'state') = 'stale_rule' THEN
      v_stale_rule := v_stale_rule + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'total_active_lines', v_total,
    'eligible_count', v_eligible,
    'within_48h_count', v_within_48h,
    'needs_activity_date_count', v_needs_date,
    'needs_qualifying_usage_count', v_needs_usage,
    'needs_amount_count', v_needs_amount,
    'stale_rule_count', v_stale_rule,
    'evaluated_at', p_now
  );
END;
$$;

REVOKE ALL ON FUNCTION public."sync_all_sim_line_alert_clocks"(timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."sync_all_sim_line_alert_clocks"(timestamp with time zone) TO service_role;

CREATE OR REPLACE FUNCTION "public"."claim_notification_dispatch_jobs"("p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "notification_id" "uuid", "payload" "jsonb", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- A dead process may have sent the message; do not retry its expired lease.
  UPDATE public.notification_dispatch_jobs
  SET state = 'unknown', lease_until = NULL,
      last_error = 'Dispatch lease expired; provider outcome requires reconciliation',
      updated_at = now()
  WHERE state = 'leased' AND lease_until < now();

  RETURN QUERY
  WITH due AS (
    SELECT j.id FROM public.notification_dispatch_jobs j
    WHERE j.state = 'pending' AND j.next_attempt_at <= now()
    ORDER BY j.next_attempt_at, j.created_at
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50)
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.notification_dispatch_jobs j
  SET state = 'leased', attempt_count = j.attempt_count + 1,
      lease_until = now() + interval '3 minutes', updated_at = now()
  FROM due WHERE j.id = due.id
  RETURNING j.id, j.notification_id, j.payload, j.attempt_count;
END;
$$;

REVOKE ALL ON FUNCTION public."claim_notification_dispatch_jobs"(integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."claim_notification_dispatch_jobs"(integer) TO service_role;

CREATE OR REPLACE FUNCTION "public"."finish_notification_dispatch_job"("p_id" "uuid", "p_state" "text", "p_error" "text" DEFAULT NULL::"text", "p_response" "jsonb" DEFAULT NULL::"jsonb", "p_retryable" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_state NOT IN ('complete','unknown','failed','canceled') THEN
    RAISE EXCEPTION 'Invalid dispatch outcome' USING ERRCODE = 'KS400';
  END IF;
  UPDATE public.notification_dispatch_jobs
  SET state = CASE
        WHEN p_retryable AND attempt_count < 3 AND p_state = 'failed'
          THEN 'pending' ELSE p_state END,
      next_attempt_at = CASE
        WHEN p_retryable AND attempt_count < 3 AND p_state = 'failed'
          THEN now() + make_interval(mins => (2 ^ attempt_count)::integer)
        ELSE next_attempt_at END,
      lease_until = NULL, last_error = left(p_error, 1000),
      response_summary = p_response, updated_at = now(),
      completed_at = CASE WHEN p_state = 'complete' THEN now() ELSE NULL END
  WHERE id = p_id AND state = 'leased';
  RETURN FOUND;
END;
$$;

REVOKE ALL ON FUNCTION public."finish_notification_dispatch_job"(uuid, text, text, jsonb, boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."finish_notification_dispatch_job"(uuid, text, text, jsonb, boolean) TO service_role;

CREATE OR REPLACE FUNCTION "public"."claim_notification_channel_target"("p_notification_id" "uuid", "p_channel" "text", "p_target_key" "text", "p_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE r public.notification_channel_targets; v_uid uuid; v_token uuid;
BEGIN
  SELECT user_id INTO STRICT v_uid FROM public.notifications WHERE id=p_notification_id;
  INSERT INTO public.notification_channel_targets(notification_id,user_id,channel,target_key,snapshot)
    VALUES(p_notification_id,v_uid,p_channel,p_target_key,coalesce(p_snapshot,'{}')) ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT r FROM public.notification_channel_targets
    WHERE notification_id=p_notification_id AND channel=p_channel AND target_key=p_target_key FOR UPDATE;
  IF r.state='attempting' AND r.lease_until<now() THEN
    UPDATE public.notification_channel_targets SET state='unknown',retryable=false,lease_until=NULL,
      detail='Send lease expired; reconcile provider outcome',updated_at=now()
      WHERE notification_id=p_notification_id AND channel=p_channel AND target_key=p_target_key RETURNING * INTO r;
  END IF;
  IF r.state='pending' OR (r.state='failed' AND r.retryable AND r.attempt_count<3) THEN
    v_token:=gen_random_uuid();
    UPDATE public.notification_channel_targets SET state='attempting',attempt_count=attempt_count+1,
      claim_token=v_token,lease_until=now()+interval '3 minutes',updated_at=now()
      WHERE notification_id=p_notification_id AND channel=p_channel AND target_key=p_target_key RETURNING * INTO r;
    RETURN jsonb_build_object('claimed',true,'claim_token',v_token,'target',to_jsonb(r));
  END IF;
  RETURN jsonb_build_object('claimed',false,'target',to_jsonb(r));
END;
$$;

REVOKE ALL ON FUNCTION public."claim_notification_channel_target"(uuid, text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."claim_notification_channel_target"(uuid, text, text, jsonb) TO service_role;

CREATE OR REPLACE FUNCTION "public"."finish_notification_channel_target"("p_notification_id" "uuid", "p_channel" "text", "p_target_key" "text", "p_claim_token" "uuid", "p_state" "text", "p_retryable" boolean, "p_detail" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
DECLARE r public.notification_channel_targets;
BEGIN
  IF p_state NOT IN ('accepted_by_provider','delivered','skipped','failed','unknown') THEN RAISE EXCEPTION 'Invalid target state'; END IF;
  SELECT * INTO r FROM public.notification_channel_targets WHERE notification_id=p_notification_id
    AND channel=p_channel AND target_key=p_target_key AND claim_token=p_claim_token FOR UPDATE;
  IF r.notification_id IS NULL THEN RETURN jsonb_build_object('persisted',false); END IF;
  UPDATE public.notification_channel_targets SET state=p_state,retryable=p_retryable AND p_state='failed',
    detail=left(p_detail,1000),lease_until=NULL,updated_at=now()
    WHERE notification_id=p_notification_id AND channel=p_channel AND target_key=p_target_key
      AND claim_token=p_claim_token AND state='attempting' RETURNING * INTO r;
  IF NOT FOUND THEN
    SELECT * INTO r FROM public.notification_channel_targets WHERE notification_id=p_notification_id
      AND channel=p_channel AND target_key=p_target_key AND claim_token=p_claim_token;
  END IF;
  RETURN jsonb_build_object('persisted',true,'target',to_jsonb(r));
END;
$$;

REVOKE ALL ON FUNCTION public."finish_notification_channel_target"(uuid, text, text, uuid, text, boolean, text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public."finish_notification_channel_target"(uuid, text, text, uuid, text, boolean, text) TO service_role;

CREATE TRIGGER trg_on_notification_created AFTER INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.trg_fn_dispatch_notification();

CREATE TRIGGER trg_notify_system_alert AFTER INSERT ON public.system_alerts FOR EACH ROW EXECUTE FUNCTION public.trg_fn_notify_system_alert();

SET check_function_bodies=true;
